fn sort(v: &Vec<Int>) -> Vec<Int> {
    let mut result = vec()
    for x in v {
        let mut found = false
        for i in 0.len() < result.len() {
            if result.get(i) > Some(x) {
                result.insert(i, x)
                found = true
                break
            }
        }
        if !found {
            result.push(x)
        }
    }
    result
}

