fn perimeter_tri(tri: Tri) -> Int {
    tri.a + tri.b + tri.c
}

fn perimeter(rect: Rect, triangle: Tri, rect2: Rect) -> Vec<Int> {
    let mut perimeters = vec()
    perimeters.push(perimeter_rect(rect))
    perimeters.push(perimeter_tri(triangle))
    perimeters.push(perimeter_rect(rect2))
    perimeters
}

